contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 val) public payable {
        uint256 balBefore = address(c).balance;
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint256 minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;
        assert(minSumAfter == val && balAfter == balBefore);
    }
    receive() external payable {}
}

