pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        uint256 balBefore = address(c).balance;
        try c.SetMinSum(val) {} catch { return; }
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(minSumAfter == val && balAfter == balBefore);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
